/**
 * Writes a cover-only listing module plus one gallery file per project
 * so a case-study page never imports another project's frames.
 */
import fs from "node:fs";
import path from "node:path";

export function writeGeneratedProjectModules({
  banner,
  projectsFile,
  loadersFile,
  loadersExportName,
  extraImports = "",
  coverImportLines,
  projectsConstName,
  projectBlocks,
  galleryEntries,
}) {
  const extra = extraImports ? `${extraImports.replace(/\n+$/, "")}\n` : "";

  const projectsContent = `/* eslint-disable import/order */
// AUTO-GENERATED by ${banner} — do not edit by hand.
${extra}
${coverImportLines.join("\n")}

export const ${projectsConstName} = [
${projectBlocks.join("\n")}
];
`;

  fs.writeFileSync(projectsFile, projectsContent, "utf8");

  const galleriesDir = path.join(path.dirname(loadersFile), "generated-galleries");
  fs.mkdirSync(galleriesDir, { recursive: true });

  const loaderLines = galleryEntries.map((entry) => {
    const galleryFile = path.join(galleriesDir, `${entry.id}.ts`);
    const galleryContent = `/* eslint-disable import/order */
// AUTO-GENERATED by ${banner} — do not edit by hand.
import type { StaticImageData } from "next/image";

${entry.importLines.join("\n")}

export const images: StaticImageData[] = [${entry.varNames.join(", ")}];
`;
    fs.writeFileSync(galleryFile, galleryContent, "utf8");
    return `  ${JSON.stringify(entry.id)}: () => import("./generated-galleries/${entry.id}").then((m) => m.images),`;
  });

  const loadersContent = `/* eslint-disable import/order */
// AUTO-GENERATED by ${banner} — do not edit by hand.
import type { StaticImageData } from "next/image";

export const ${loadersExportName}: Record<
  string,
  () => Promise<StaticImageData[]>
> = {
${loaderLines.join("\n")}
};
`;

  fs.writeFileSync(loadersFile, loadersContent, "utf8");
}
